export const tutorial = { id: "rc-line-edit", title: "LineEdit 单行输入", steps: [
    { ...{"id":"step-1","title":"试一试输入","goal":"切换填充与描边，输入或清除项目名称。","why":"业务状态保存输入值，标签说明输入目的，长度限制要在输入前可见。","instruction":"输入名称，再切换外观和清除内容。","expected":"外观切换保留输入，清除后焦点返回字段，计数与预览同步。","changes":["使用 label、supportingText 和 appearance 配置字段。"],"sourceCode":"import { useState } from \"react\";\nimport { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport LineEdit from \"@crab-dev/rc-line-edit\";\nimport Button from \"@crab-dev/rc-button\";\n\nconst stage = css`\n    display: grid;\n    gap: ${token.space['section-gap']};\n    width: 100%;\n    max-width: calc(${token.size['40']} * 12);\n    min-width: 0;\n`;\nconst choices = css`display: flex; flex-wrap: wrap; gap: ${token.space['component-gap']};`;\nconst result = css`\n    color: ${token.color.text.secondary};\n    display: flex;\n    flex-wrap: wrap;\n    gap: ${token.space['component-gap']};\n    overflow-wrap: anywhere;\n    font-size: ${token.typography.body.medium['font-size']};\n    line-height: ${token.typography.body.medium['line-height']};\n    & span:last-child { color: ${token.color.text.primary}; min-width: 0; }\n`;\n\nexport default function Example() {\n    const [value, setValue] = useState(\"下一件好作品\");\n    const [appearance, setAppearance] = useState<\"filled\" | \"outlined\">(\"filled\");\n    return <div className={stage}>\n            <div className={choices} role=\"group\" aria-label=\"输入框外观\">\n                <Button appearance={appearance === \"filled\" ? \"tonal\" : \"text\"} aria-pressed={appearance === \"filled\"} onClick={() => setAppearance(\"filled\")}>填充 Filled</Button>\n                <Button appearance={appearance === \"outlined\" ? \"tonal\" : \"text\"} aria-pressed={appearance === \"outlined\"} onClick={() => setAppearance(\"outlined\")}>描边 Outlined</Button>\n            </div>\n            <LineEdit label=\"项目名称\" appearance={appearance} value={value} onChange={event => setValue(event.target.value)}\n                supportingText=\"起一个容易记住的名字，最多 30 字。\" maxLength={30} showCount allowClear onClear={() => setValue(\"\")} />\n            <output className={result}><span>当前值</span><span>{value || \"等待新的灵感\"}</span></output>\n    </div>;\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-line-edit/step-1.js") } },
    { ...{"id":"step-2","title":"两种外观","goal":"并排体验 Filled 与 Outlined。","why":"业务状态保存输入值，标签说明输入目的，长度限制要在输入前可见。","instruction":"聚焦空字段，输入内容后移开焦点。","expected":"标签浮起，输入后保持可见，边界提供焦点反馈。","changes":["使用相同结构呈现两种外观。"],"sourceCode":"import { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport LineEdit from \"@crab-dev/rc-line-edit\";\n\nconst layout = css`\n    display: grid;\n    width: 100%;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: ${token.space['group-gap']};\n    & section { display: grid; align-content: start; gap: ${token.space['section-gap']}; min-width: 0; }\n    & h3 { margin: 0; font-size: ${token.typography.title.large['font-size']}; font-weight: ${token.typography.title.large.emphasized['font-weight']}; }\n    & p { margin: 0; color: ${token.color.text.secondary}; font-size: ${token.typography.body.medium['font-size']}; line-height: ${token.typography.body.medium['line-height']}; }\n    @media (max-width: 600px) { grid-template-columns: minmax(0, 1fr); }\n`;\n\nexport default function Example() {\n    return <div className={layout}>\n        <section aria-label=\"填充外观\">\n            <h3>Filled · 填充</h3>\n            <p>用表面色建立输入区域，适合成组表单。</p>\n            <LineEdit label=\"团队名称\" appearance=\"filled\" placeholder=\"例如：产品设计组\" supportingText=\"聚焦试试：标签上移，底线强调。\" />\n        </section>\n        <section aria-label=\"描边外观\">\n            <h3>Outlined · 描边</h3>\n            <p>用轮廓明确边界，适合需要轻盈背景的页面。</p>\n            <LineEdit label=\"显示名称\" appearance=\"outlined\" placeholder=\"例如：林小蟹\" supportingText=\"开始输入后，标签仍然可见。\" />\n        </section>\n    </div>;\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-line-edit/step-2.js") } },
    { ...{"id":"step-3","title":"状态与反馈","goal":"体验错误恢复、密码核对、只读和禁用。","why":"输入状态需要可见文字与辅助技术同时感知。","instruction":"补全联系邮箱并移开焦点，切换密码可见性。","expected":"有效邮箱恢复辅助说明，密码值保持不变。","changes":["使用 errorText 自动关联错误原因。"],"sourceCode":"import LineEdit from \"@crab-dev/rc-line-edit\";\nimport { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport { useState } from \"react\";\n\nconst grid = css`\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: ${token.space['group-gap']};\n    width: 100%;\n    padding-block: ${token.space['section-gap']};\n    @media (max-width: 600px) { grid-template-columns: minmax(0, 1fr); }\n`;\n\nexport default function Example() {\n    const [email, setEmail] = useState(\"hello@\");\n    const [checked, setChecked] = useState(true);\n    const valid = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email);\n    return <div className={grid}>\n        <LineEdit label=\"联系邮箱\" type=\"email\" value={email}\n            onChange={event => { setEmail(event.target.value); setChecked(false); }}\n            onBlur={() => setChecked(true)}\n            supportingText=\"用于接收项目邀请。\"\n            errorText={checked && !valid ? \"邮箱不完整，请补全域名，例如 hello@crab.dev。\" : undefined} />\n        <LineEdit label=\"访问密码\" type=\"password\" defaultValue=\"Crab-design-3\" supportingText=\"点击眼睛图标核对内容。\" />\n        <LineEdit label=\"项目编号\" readOnly defaultValue=\"CRAB-2026-001\" supportingText=\"只读：仍可聚焦、选择与复制。\" />\n        <LineEdit appearance=\"filled\" label=\"团队空间\" disabled defaultValue=\"设计工作室\" supportingText=\"暂不可编辑，请联系空间管理员。\" />\n    </div>;\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-line-edit/step-3.js") } }
] } satisfies TutorialRecord;
